299.         proof! { admit(); }
300.         let frame_number: usize = frame.into_frame_number().into_raw_value();
301. 
302.         if frame_number >= self.refcount.len() {
303.             let reason: &str = "frame number out of bounds";
304.             #[cfg(not(verus_keep_ghost))]
305.             error!("{reason} (frame={frame:?})");
306.             return Err(Error::new(ErrorCode::BadAddress, reason));
307.         }
308. 
309.         // Reject double-frees: the frame must currently have at least one owner.
310.         if self.refcount[frame_number] == 0 {
311.             let reason: &str = "frame is already free";
312.             #[cfg(not(verus_keep_ghost))]
